import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

/**
 * `THIRD-PARTY-NOTICES.md` reaches an installer through two things agreeing,
 * and neither is visible from the other.
 *
 * The file is generated by `beforeBuildCommand` and never committed, so it
 * cannot be listed in `tauri.conf.json`: `tauri-build` fails the *compile*
 * when a resource path does not exist, which would mean no `cargo test` and no
 * `cargo clippy` without generating it first. It is listed in a release-only
 * `--config` overlay instead.
 *
 * Which leaves one silent way to ship out of compliance: a release build that
 * forgets the overlay. symphonia is MPL-2.0 and the installer is the only
 * place its notice reaches anybody, so that is worth a test rather than a
 * comment. The other half of the guard is in the config itself - the overlay
 * names a literal path, so a bundler that gets there without the file fails
 * loudly.
 */
const root = `${process.cwd().replaceAll("\\", "/")}/`;
const NOTICES = "../THIRD-PARTY-NOTICES.md";

function read(path: string): string {
  return readFileSync(`${root}${path}`, "utf8");
}

describe("the third-party notices", () => {
  const base = JSON.parse(read("src-tauri/tauri.conf.json"));
  const release = JSON.parse(read("src-tauri/tauri.release.conf.json"));
  const releaseWorkflow = read(".github/workflows/release.yml");

  it("is not a resource of the base config, which has to compile without it", () => {
    expect(base.bundle.resources).not.toContain(NOTICES);
  });

  it("is a resource of the release overlay", () => {
    expect(release.bundle.resources).toContain(NOTICES);
  });

  it("does not lose the resources the base config already had", () => {
    // A `--config` overlay replaces an array rather than extending it, so
    // anything the base lists has to be repeated here or it stops shipping.
    for (const resource of base.bundle.resources) {
      expect(release.bundle.resources).toContain(resource);
    }
  });

  it("is generated before every build", () => {
    expect(base.build.beforeBuildCommand).toContain("npm run notices");
  });

  it("is asked for by the release workflow", () => {
    expect(releaseWorkflow).toContain("--config src-tauri/tauri.release.conf.json");
  });
});
